//! Cross tests (cr-uzkn): the same scenario with every pairing of
//! {go crane, crane-rs} client x {go registry, crane-rs registry}.
//! All four transcripts must be identical (registry address normalised to REG),
//! and anything pushed must survive `crane validate --remote` from go.
//! Inputs are generated byte-for-byte by crane::fixture; no network beyond loopback.

mod common;

use std::collections::BTreeMap;
use std::path::Path;

use common::*;
use crane::digest;
use crane::fixture::{Image, docker_tarball, oci_layout};

struct Fixtures {
    dir: tempfile::TempDir,
    img1: Image,
    img2: Image,
    img3: Image,
}

impl Fixtures {
    fn new() -> Self {
        let dir = tempfile::tempdir().unwrap();
        let img1 = Image::new(11, 3, 2000, "linux", "amd64");
        let img2 = Image::new(12, 1, 300, "linux", "amd64");
        let img3 = Image::new(13, 2, 500, "linux", "arm64");
        std::fs::write(
            dir.path().join("img1.tar"),
            docker_tarball(&[("cross/img:t1", &img1)]),
        )
        .unwrap();
        oci_layout(&dir.path().join("one"), &[&img2], false).unwrap();
        oci_layout(&dir.path().join("multi"), &[&img1, &img3], true).unwrap();
        oci_layout(&dir.path().join("two"), &[&img2, &img3], false).unwrap();
        Self {
            dir,
            img1,
            img2,
            img3,
        }
    }
    fn path(&self, p: &str) -> String {
        self.dir.path().join(p).display().to_string()
    }
}

/// Ordered (step, ok, normalised stdout) for one client against one registry.
type Transcript = Vec<(String, bool, String)>;

fn scenario(client: &Path, reg: &Reg, fx: &Fixtures) -> Transcript {
    let work = tempfile::tempdir().unwrap();
    let r = |s: &str| s.replace("REG", &reg.addr);
    let mut t: Transcript = Vec::new();
    let mut step = |name: &str, args: &[String]| -> Out {
        let args: Vec<&str> = args.iter().map(String::as_str).collect();
        let o = run(client, &args);
        let mut norm = o.text().replace(&reg.addr, "REG");
        if name.starts_with("catalog") {
            // go's registry returns _catalog in Go map order (random); the spec says lexical.
            // Ordering is a registry property, not a client one, so compare as a set.
            let mut lines: Vec<&str> = norm.lines().collect();
            lines.sort_unstable();
            norm = lines.iter().map(|l| format!("{l}\n")).collect();
        }
        t.push((
            name.to_string(),
            o.ok,
            if o.ok { norm } else { String::new() },
        ));
        o
    };
    let a = |v: &[&str]| v.iter().map(|s| r(s)).collect::<Vec<_>>();
    let cfg1 = digest::of(&fx.img1.config);

    // pushes
    step(
        "push tarball",
        &a(&["push", &fx.path("img1.tar"), "REG/cross/img:t1"]),
    );
    step(
        "push layout image",
        &a(&["push", &fx.path("one"), "REG/cross/oci:one"]),
    );
    step(
        "push layout index",
        &a(&["push", &fx.path("multi"), "REG/cross/multi:latest"]),
    );
    step(
        "push layout --index",
        &a(&["push", "--index", &fx.path("two"), "REG/cross/two:idx"]),
    );
    step(
        "push layout many without --index",
        &a(&["push", &fx.path("two"), "REG/cross/two:bad"]),
    );
    step(
        "push missing path",
        &a(&["push", &fx.path("nope"), "REG/cross/x:y"]),
    );

    // reads
    step("digest", &a(&["digest", "REG/cross/img:t1"]));
    step(
        "digest --full-ref",
        &a(&["digest", "--full-ref", "REG/cross/img:t1"]),
    );
    step("manifest", &a(&["manifest", "REG/cross/img:t1"]));
    step("config", &a(&["config", "REG/cross/img:t1"]));
    step("blob", &a(&["blob", &format!("REG/cross/img@{cfg1}")]));
    step(
        "blob missing",
        &a(&["blob", &format!("REG/cross/img@{}", digest::of(b"none"))]),
    );
    step("manifest oci", &a(&["manifest", "REG/cross/oci:one"]));
    step("config oci", &a(&["config", "REG/cross/oci:one"]));
    step("digest index", &a(&["digest", "REG/cross/multi"]));
    step("manifest index", &a(&["manifest", "REG/cross/multi"]));
    step(
        "config index default platform",
        &a(&["config", "REG/cross/multi"]),
    );
    step(
        "digest index arm64",
        &a(&["digest", "--platform", "linux/arm64", "REG/cross/multi"]),
    );
    step(
        "manifest index arm64",
        &a(&["manifest", "--platform", "linux/arm64", "REG/cross/multi"]),
    );
    step(
        "config index arm64",
        &a(&["config", "--platform", "linux/arm64", "REG/cross/multi"]),
    );
    step(
        "config index missing platform",
        &a(&["config", "--platform", "linux/s390x", "REG/cross/multi"]),
    );
    step(
        "manifest --index push",
        &a(&["manifest", "REG/cross/two:idx"]),
    );
    step("manifest unknown", &a(&["manifest", "REG/cross/img:nope"]));
    step(
        "manifest unknown repo",
        &a(&["manifest", "REG/cross/none:x"]),
    );

    // tags
    step("tag", &a(&["tag", "REG/cross/img:t1", "t2"]));
    step(
        "tag digest-like",
        &a(&["tag", "REG/cross/img:t1", "sha256-0000"]),
    );
    step("ls", &a(&["ls", "REG/cross/img"]));
    step("ls --full-ref", &a(&["ls", "--full-ref", "REG/cross/img"]));
    step("ls -O", &a(&["ls", "-O", "REG/cross/img"]));
    step("ls unknown", &a(&["ls", "REG/cross/none"]));
    step("digest t2", &a(&["digest", "REG/cross/img:t2"]));

    // copies (same registry: exercises cross-repo mount)
    step(
        "copy",
        &a(&["copy", "REG/cross/img:t1", "REG/cross/copy:c1"]),
    );
    step(
        "copy index",
        &a(&["copy", "REG/cross/multi", "REG/cross/multicopy:x"]),
    );
    step(
        "copy --platform",
        &a(&[
            "copy",
            "--platform",
            "linux/arm64",
            "REG/cross/multi",
            "REG/cross/arm:only",
        ]),
    );
    step("digest copy", &a(&["digest", "REG/cross/copy:c1"]));
    step(
        "digest copy index",
        &a(&["digest", "REG/cross/multicopy:x"]),
    );
    step(
        "digest copy platform",
        &a(&["digest", "REG/cross/arm:only"]),
    );
    step("catalog", &a(&["catalog", "REG"]));
    step("catalog --full-ref", &a(&["catalog", "--full-ref", "REG"]));

    // pull and push back: digests must survive the round trip
    let tar = work.path().join("pulled.tar").display().to_string();
    let tar2 = work.path().join("pulled2.tar").display().to_string();
    let lay = work.path().join("pulled-oci").display().to_string();
    step("pull tarball", &a(&["pull", "REG/cross/img:t1", &tar]));
    step(
        "push pulled tarball",
        &a(&["push", &tar, "REG/cross/repush:tar"]),
    );
    let d1 = step("digest img", &a(&["digest", "REG/cross/img:t1"])).text();
    step(
        "pull by digest",
        &a(&["pull", &format!("REG/cross/img@{}", d1.trim()), &tar2]),
    );
    step(
        "push pulled-by-digest tarball",
        &a(&["push", &tar2, "REG/cross/repush:dig"]),
    );
    step(
        "pull two refs",
        &a(&[
            "pull",
            "REG/cross/img:t1",
            "REG/cross/oci:one",
            &work.path().join("two.tar").display().to_string(),
        ]),
    );
    step(
        "pull oci index",
        &a(&["pull", "--format", "oci", "REG/cross/multi", &lay]),
    );
    step(
        "push pulled layout",
        &a(&["push", &lay, "REG/cross/repush:oci"]),
    );
    step(
        "pull missing",
        &a(&[
            "pull",
            "REG/cross/none:x",
            &work.path().join("x.tar").display().to_string(),
        ]),
    );

    // deletes
    let dcopy = step(
        "digest copy before delete",
        &a(&["digest", "REG/cross/copy:c1"]),
    )
    .text();
    step(
        "delete by digest",
        &a(&["delete", &format!("REG/cross/copy@{}", dcopy.trim())]),
    );
    step(
        "manifest after delete",
        &a(&["manifest", &format!("REG/cross/copy@{}", dcopy.trim())]),
    );
    step(
        "delete unknown",
        &a(&["delete", &format!("REG/cross/copy@{}", digest::of(b"none"))]),
    );
    t
}

#[test]
fn four_way_transcripts_match() {
    let fx = Fixtures::new();
    let (go, rs) = (go_crane(), rust_crane());
    let mut results: BTreeMap<String, Transcript> = BTreeMap::new();
    // CROSS_REGISTRIES=go (or rust) narrows the run while debugging; default is both.
    let kinds = std::env::var("CROSS_REGISTRIES").unwrap_or_else(|_| "go,rust".into());
    for rname in ["go-registry", "rust-registry"]
        .into_iter()
        .filter(|r| kinds.split(',').any(|k| r.starts_with(k)))
    {
        for (cname, bin) in [("go-client", &go), ("rust-client", &rs)] {
            // a fresh registry per pairing, so every scenario starts from the same state
            let reg = if rname == "go-registry" {
                go_registry()
            } else {
                rust_registry()
            };
            results.insert(format!("{cname} x {rname}"), scenario(bin, &reg, &fx));
        }
    }
    let (first_name, first) = results.iter().next().unwrap();
    let mut diffs = Vec::new();
    for (name, t) in &results {
        assert_eq!(t.len(), first.len());
        for (a, b) in first.iter().zip(t) {
            if a != b {
                diffs.push(format!(
                    "step {:?}:\n  {first_name}: ok={} {:?}\n  {name}: ok={} {:?}",
                    a.0, a.1, a.2, b.1, b.2
                ));
            }
        }
    }
    assert!(
        diffs.is_empty(),
        "transcripts differ:\n{}",
        diffs.join("\n")
    );
    // sanity: the scenario really did succeed where it should
    let ok: BTreeMap<&str, bool> = first.iter().map(|(n, ok, _)| (n.as_str(), *ok)).collect();
    for must_fail in [
        "push layout many without --index",
        "push missing path",
        "blob missing",
        "config index missing platform",
        "manifest unknown",
        "manifest unknown repo",
        "ls unknown",
        "pull missing",
        "manifest after delete",
        "delete unknown",
    ] {
        assert!(!ok[must_fail], "{must_fail} should fail");
    }
    assert_eq!(ok.values().filter(|v| **v).count(), ok.len() - 10, "{ok:?}");
    // pushes are digest-stable through pull round trips
    let get = |n: &str| first.iter().find(|s| s.0 == n).unwrap().2.clone();
    let digest_of = |line: String| line.trim().rsplit('@').next().unwrap().to_string();
    assert_eq!(digest_of(get("push tarball")), get("digest").trim());
    assert_eq!(digest_of(get("push pulled tarball")), get("digest").trim());
    assert_eq!(
        digest_of(get("push pulled-by-digest tarball")),
        get("digest").trim()
    );
    assert_eq!(
        digest_of(get("push pulled layout")),
        get("digest index").trim()
    );
    assert_eq!(get("digest copy index"), get("digest index"));
    assert_eq!(get("digest copy platform"), get("digest index arm64"));
    assert_eq!(
        get("config index arm64").as_bytes(),
        fx.img3.config.as_slice()
    );
    assert_eq!(get("config").as_bytes(), fx.img1.config.as_slice());
    assert_eq!(get("config oci").as_bytes(), fx.img2.config.as_slice());
    assert_eq!(get("ls -O"), "t1\nt2\n");
}

#[test]
fn go_validates_what_rust_pushes_to_rust_registry() {
    let fx = Fixtures::new();
    let (go, rs) = (go_crane(), rust_crane());
    let reg = rust_registry();
    let r = |s: &str| s.replace("REG", &reg.addr);
    ok(&rs, &["push", &fx.path("img1.tar"), &r("REG/v/img:1")]);
    ok(&rs, &["push", &fx.path("multi"), &r("REG/v/multi:1")]);
    ok(&rs, &["copy", &r("REG/v/multi:1"), &r("REG/v/copy:1")]);
    for target in ["REG/v/img:1", "REG/v/multi:1", "REG/v/copy:1"] {
        let o = run(&go, &["validate", "--remote", &r(target)]);
        assert!(o.ok, "go validate {target}: {}{}", o.text(), o.stderr);
    }
}

#[test]
fn copy_between_registries_both_directions() {
    let fx = Fixtures::new();
    let (go, rs) = (go_crane(), rust_crane());
    let (greg, rreg) = (go_registry(), rust_registry());
    ok(
        &go,
        &[
            "push",
            &fx.path("multi"),
            &format!("{}/x/multi:1", greg.addr),
        ],
    );
    let want = ok(&go, &["digest", &format!("{}/x/multi:1", greg.addr)]).text();
    for (i, client) in [&go, &rs].into_iter().enumerate() {
        let to_rust = format!("{}/x/multi:from-go-{i}", rreg.addr);
        ok(
            client,
            &["copy", &format!("{}/x/multi:1", greg.addr), &to_rust],
        );
        assert_eq!(ok(client, &["digest", &to_rust]).text(), want);
        let back = format!("{}/x/back:{i}", greg.addr);
        ok(client, &["copy", &to_rust, &back]);
        assert_eq!(ok(client, &["digest", &back]).text(), want);
    }
}

/// A real linux/amd64 docker-save tarball given in $CRANE_REAL_TAR (skipped when unset):
/// push, check the config platform, tag latest, as a release script would.
#[test]
fn real_tarball_when_given() {
    let Ok(p) = std::env::var("CRANE_REAL_TAR") else {
        eprintln!("skipping: set CRANE_REAL_TAR to a linux/amd64 docker-save tarball");
        return;
    };
    assert!(Path::new(&p).is_file(), "CRANE_REAL_TAR={p} is not a file");
    let (go, rs) = (go_crane(), rust_crane());
    let mut digests = Vec::new();
    for reg in [go_registry(), rust_registry()] {
        for client in [&go, &rs] {
            let image = format!("{}/example-app:test", reg.addr);
            let pushed = ok(client, &["push", &p, &image, "--insecure"]).text();
            let cfg = ok(client, &["config", &image, "--insecure"]).text();
            let v: serde_json::Value = serde_json::from_str(&cfg).unwrap();
            assert_eq!(
                (v["os"].as_str(), v["architecture"].as_str()),
                (Some("linux"), Some("amd64"))
            );
            ok(client, &["tag", &image, "latest", "--insecure"]);
            assert!(
                ok(client, &["ls", &format!("{}/example-app", reg.addr)])
                    .text()
                    .contains("latest\n")
            );
            digests.push(pushed.trim().rsplit('@').next().unwrap().to_string());
        }
    }
    digests.dedup();
    assert_eq!(digests.len(), 1, "push digests differ: {digests:?}");
}
